"""Render 30 fictional articles from a single numeric product catalog."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
c=json.loads((ROOT/'product_catalog.json').read_text()); p=c['products']; docs=[]
def add(id,product,title,body,aliases=''):
 docs.append(dict(id=id,product=product,title=title,content=body,aliases=aliases,version=c['version'],valid_from=c['valid_from'],kind='fictional',source='Учебная база Демо-банка',disclaimer=c['disclaimer']))
x=p['debit']; n=x['name']
add('D01','debit',f'{n}: назначение и условия',f'{n} — дебетовая карта для повседневных покупок за собственные деньги. Кредитного лимита нет. Доступна гражданам РФ от {x["age"]} лет. Выпуск и обслуживание — {x["service_month"]} ₽ в месяц без требований к остатку. Валюта — рубли. За обычные покупки начисляется {x["cashback_pct"]}% рублями, максимум {x["cashback_cap_month"]} ₽ за календарный месяц. Переводы, снятие наличных и платежи по реквизитам кэшбэк не приносят. Это учебный продукт.','дебетовка обычная карта бесплатная зарплата кешбэк')
add('D02','debit',f'Как оформить {n}',f'Чтобы оформить дебетовую карту {n}, в учебном приложении откройте «Продукты» → «Карты» → «Каждый день» → «Оформить». Укажите ФИО, телефон и адрес доставки, проверьте условия и выберите встречу с представителем. Заявитель — гражданин РФ от {x["age"]} лет, нужен паспорт РФ. Доставка бесплатная, занимает {x["delivery_min_days"]}–{x["delivery_max_days"]} рабочих дней после подтверждения заявки. На встрече предъявите оригинал паспорта. Прототип объясняет процесс, но заявку не отправляет.','заказать получить заявка документы паспорт дебетовая')
add('D03','debit',f'{n}: получение и активация',f'После получения {n} откройте её в учебном приложении, нажмите «Активировать» и задайте ПИН в защищённом разделе приложения. ПИН, CVV и коды из СМС никому не сообщайте и не вводите в этот чат. Для первой покупки с пластиковой картой используйте терминал с вводом ПИН. Доставка занимает {x["delivery_min_days"]}–{x["delivery_max_days"]} рабочих дней после подтверждения заявки. Конкретную дату, статус заявки и готовность карты чат проверить не может.','активация как начать пользоваться доставили пластиковая')
add('D04','debit',f'{n}: наличные и кэшбэк',f'По карте {n} можно снимать до {x["cash_free_month"]} ₽ за календарный месяц без комиссии в учебных банкоматах Демо-банка. С суммы превышения взимается {x["cash_over_pct"]}%, минимум {x["cash_over_min"]} ₽ за снятие. Сторонний банкомат может иметь свою комиссию, она в базе не определена. Кэшбэк {x["cashback_pct"]}% за покупки, до {x["cashback_cap_month"]} ₽ в месяц, начисляется в последний день следующего месяца. Возврат покупки отменяет соответствующий кэшбэк.','снять банкомат комиссия лимит бонусы начисление кешбэк')
x=p['credit']; n=x['name']
add('C01','credit',f'{n}: лимит и стоимость',f'{n} — кредитная карта с заёмными деньгами банка для покупок. Учебный лимит от {x["limit_min"]} до {x["limit_max"]} ₽; конкретный лимит определяется индивидуально после рассмотрения. Обслуживание {x["service_month"]} ₽ в месяц. Льготный период на покупки до {x["grace_days"]} дней при полном погашении суммы по выписке в срок. Если условия льготы не соблюдены, ставка {x["rate_pct"]}% годовых. Решение об одобрении и персональный лимит чат не определяет.','кредитка кредитный лимит процент ставка обслуживание')
add('C02','credit',f'Как оформить {n}',f'Карта {n} доступна гражданам РФ в возрасте от {x["age"]} до {x["age_max"]} лет с постоянным доходом. В учебном приложении: «Продукты» → «Карты» → «Запас» → «Подать заявку». Нужен паспорт РФ; в анкете указывают занятость и доход. При рассмотрении могут запросить подтверждение дохода. После решения клиент знакомится с индивидуальными условиями и выбирает получение карты. Одобрение не гарантируется, срок рассмотрения в базе не установлен. Прототип заявку не отправляет.','получить кредитную карту документы требования возраст доход')
add('C03','credit',f'{n}: льготный период и платёж',f'По {n} льготный период до {x["grace_days"]} дней относится только к покупкам. Для сохранения льготы нужно полностью погасить сумму по выписке до указанной в ней даты. Минимальный ежемесячный платёж — {x["payment_pct"]}% задолженности по основному долгу плюс начисленные проценты и комиссии; минимум {x["payment_min"]} ₽, но не больше всей задолженности. Внесение только минимального платежа не сохраняет льготу. Сумма и дата платежа видны в выписке приложения; доступа к ней у чата нет.','грейс беспроцентный период погашение задолженность минимальный платеж')
add('C04','credit',f'{n}: снятие наличных и ограничения',f'Снятие наличных с {n} стоит {x["cash_fee_pct"]}% от суммы плюс {x["cash_fee_fixed"]} ₽ за операцию. На наличные и переводы льготный период не распространяется: проценты {x["rate_pct"]}% годовых начисляются со дня операции. Тариф комиссии за переводы с кредитной карты в учебной базе не задан — проверьте индивидуальные условия в приложении. Кредитную карту не стоит путать с дебетовой: расходуются заёмные средства, которые нужно вернуть.','кредитка наличные переводы комиссия за снятие')
x=p['junior']; n=x['name']
add('J01','junior',f'{n}: детская карта',f'{n} — детская дебетовая карта для детей от {x["age"]} до {x["age_max"]} лет включительно. Она привязана к счёту родителя или законного представителя. Собственного кредитного лимита у ребёнка нет. Выпуск и обслуживание {x["service_month"]} ₽ в месяц. Родитель видит покупки и задаёт ограничения в своём приложении. Базовый дневной лимит покупок {x["default_limit_day"]} ₽, его можно изменить. Кэшбэк для этого продукта не предусмотрен.','карта ребенку школьник подросток родитель детская')
add('J02','junior',f'Как оформить {n} ребёнку',f'Заявку на {n} подаёт родитель или законный представитель с дебетовой картой Демо-банка. В его приложении: «Продукты» → «Карты» → «Старт» → «Оформить ребёнку». Нужны паспорт родителя и свидетельство о рождении ребёнка; если ребёнок уже получил паспорт, нужны также его паспортные данные. Возраст ребёнка — {x["age"]}–{x["age_max"]} лет. Доставка бесплатная, {x["delivery_min_days"]}–{x["delivery_max_days"]} рабочих дней после подтверждения заявки. Прототип не собирает документы и не оформляет карту.','как заказать ребенку документы свидетельство паспорт родителя')
add('J03','junior',f'{n}: родительские ограничения',f'В учебном приложении родителя откройте {n} → «Лимиты». Можно изменить дневной предел покупок, отключить снятие наличных и интернет-покупки. Исходный предел покупок — {x["default_limit_day"]} ₽ в день. Родитель видит историю расходов ребёнка. Пополнение выполняется переводом со счёта родителя. Чат не видит баланс, не меняет лимиты и не переводит деньги.','контроль расходы ребенка лимит запрет онлайн покупки')
add('J04','junior',f'{n}: получение и потеря карты',f'После получения {n} родитель активирует карту в своём приложении в разделе детской карты. Если карта потеряна, родитель открывает «Старт» → «Настройки» → «Заблокировать» и связывается с поддержкой через приложение для перевыпуска. При неизвестных списаниях нужна проверка сотрудником. Чат не выполняет блокировку и не соединяет с реальным оператором. Стоимость перевыпуска в базе не определена.','детская активация потеря блокировка перевыпуск')
x=p['savings']; n=x['name']
add('S01','savings',f'{n}: условия накопительного счёта',f'{n} — рублёвый накопительный счёт со свободным пополнением и снятием. Учебная ставка {x["rate_pct"]}% годовых на ежедневный остаток. Минимальный остаток {x["min_balance"]} ₽, обслуживание {x["service_month"]} ₽. Ставка переменная: при изменении условий применяется новая опубликованная ставка с даты вступления в силу, без пересчёта прошлых дней. Фиксированного срока нет. Это накопительный счёт, а не срочный вклад.','накопления сберегательный проценты остаток хранить деньги')
add('S02','savings',f'Как открыть {n}',f'{n} доступен гражданам РФ от {x["age"]} лет. Действующий идентифицированный клиент открывает в учебном приложении «Продукты» → «Сбережения» → «Копилка» → «Открыть счёт» и подтверждает условия. Новому клиенту сначала нужна идентификация по паспорту РФ. Открытие и обслуживание бесплатные; обязательного первоначального взноса нет. Прототип объясняет шаги, но счёт не открывает.','открытие накопительного документы паспорт минимальная сумма')
add('S03','savings',f'{n}: начисление процентов',f'На счёте {n} проценты рассчитываются ежедневно по ставке {x["rate_pct"]}% годовых на фактический остаток и выплачиваются в последний день месяца на этот же счёт. Для учебного расчёта используйте сумму ежедневных остатков × годовую ставку / число дней в соответствующем году. После выплаты процентов они входят в остаток следующих дней. Налогообложение в учебной базе не моделируется.','когда начисляются выплата доход доходность расчет капитализация')
add('S04','savings',f'{n}: пополнение снятие и закрытие',f'{n} можно пополнять и выводить деньги в любой день переводом между своими счетами Демо-банка без комиссии. Минимальный остаток {x["min_balance"]} ₽. Снятие не отменяет уже начисленные проценты за прошлые дни, но уменьшает остаток для следующих начислений. Для закрытия: «Копилка» → «Настройки» → «Закрыть счёт»; остаток и начисленные проценты переводятся на выбранный собственный счёт. Чат эти действия не выполняет.','досрочно забрать накопительный снять закрыть пополнить')
x=p['deposit']; n=x['name']
add('V01','deposit',f'{n}: условия вклада',f'{n} — рублёвый срочный вклад на {x["term_months"]} месяцев со ставкой {x["rate_pct"]}% годовых, фиксированной на срок договора. Минимальная сумма {x["min_amount"]} ₽. Проценты выплачиваются в конце срока на выбранный счёт, капитализации внутри срока нет. Пополнение и частичное снятие не предусмотрены. Автоматического продления нет. Подходит для суммы, которую клиент готов разместить на весь срок.','депозит положить деньги фиксированная доходность ставка срок')
add('V02','deposit',f'Как открыть {n}',f'{n} доступен гражданам РФ от {x["age"]} лет после идентификации по паспорту РФ. В учебном приложении: «Продукты» → «Сбережения» → «Горизонт» → «Открыть вклад». Выберите собственный счёт списания, сумму от {x["min_amount"]} ₽, проверьте срок {x["term_months"]} месяцев и ставку {x["rate_pct"]}% годовых, подтвердите условия. Прототип не принимает деньги и не заключает договор.','открыть вклад документы оформить минимальный взнос')
add('V03','deposit',f'{n}: проценты и окончание срока',f'По вкладу {n} проценты выплачиваются в конце {x["term_months"]}-месячного срока. Ставка {x["rate_pct"]}% годовых, расчёт по фактическому числу дней размещения и календарных дней в году. В конце срока сумма вклада и проценты поступают на выбранный собственный счёт. Автопродления нет. Налоги и страхование вкладов для вымышленного банка не моделируются; правила реальных банков из этого примера выводить нельзя.','когда вернут вклад окончание выплата продление доход')
add('V04','deposit',f'{n}: досрочное закрытие',f'Пополнить {n} или снять только часть суммы нельзя. При досрочном закрытии возвращается вся сумма, а проценты за весь фактический срок пересчитываются по {x["early_rate_pct"]}% годовых вместо {x["rate_pct"]}%. В учебном приложении: «Горизонт» → «Закрыть досрочно» → проверьте расчёт → подтвердите. Для свободного доступа к деньгам в каталоге есть накопительный счёт Копилка. Чат не закрывает вклад.','забрать раньше частично снять пополнение потеря процентов')
x=p['loan']; n=x['name']
add('L01','loan',f'{n}: условия кредита наличными',f'{n} — учебный кредит наличными от {x["amount_min"]} до {x["amount_max"]} ₽ на срок от {x["term_min_months"]} до {x["term_max_months"]} месяцев. Ставка {x["rate_pct"]}% годовых фиксирована в учебном сценарии. Выплаты ежемесячные, аннуитетные. Комиссии за выдачу нет, обязательная платная страховка в модели отсутствует. Конкретные сумма, срок и решение определяются при рассмотрении заявки; чат не гарантирует одобрение.','потребительский кредит занять деньги сумма срок проценты')
add('L02','loan',f'Как подать заявку на {n}',f'{n} доступен гражданам РФ от {x["age"]} до {x["age_max"]} лет с постоянным доходом. В учебном приложении: «Продукты» → «Кредиты» → «План» → «Подать заявку». Нужны паспорт РФ и подтверждение дохода; в анкете указывают занятость, доход и желаемые сумму и срок. После рассмотрения нужно изучить индивидуальные условия и график. Решение и срок рассмотрения чат не знает; документы в чат отправлять не нужно.','документы кредит наличными справка доход заявка требования')
add('L03','loan',f'{n}: ежемесячные платежи',f'По кредиту {n} ежемесячный аннуитетный платёж включает основной долг и проценты. Точная сумма и дата указаны в индивидуальном графике приложения. Ставка учебного продукта {x["rate_pct"]}% годовых, срок {x["term_min_months"]}–{x["term_max_months"]} месяцев. Пополняйте счёт погашения к дате платежа. При трудностях обратитесь в поддержку для обсуждения ситуации; чат не обещает отсрочку и не меняет график.','график платеж аннуитет погашение задолженность просрочка')
add('L04','loan',f'{n}: досрочное погашение',f'Кредит {n} можно погасить полностью или частично досрочно без отдельной комиссии. В учебном приложении откройте «План» → «Досрочное погашение», выберите сумму и дату, пополните счёт и подтвердите заявку. При частичном погашении можно выбрать уменьшение срока или ежемесячного платежа. Проценты рассчитываются за фактическое пользование долгом. Чат не подаёт заявку и не подтверждает погашение.','закрыть кредит раньше досрочка уменьшить срок платеж')
add('G01','general','Каталог продуктов Демо-банка','В Демо-банке шесть учебных продуктов: карта Каждый день — дебетовая для ежедневных покупок за собственные деньги; карта Запас — кредитная для покупок за заёмные средства; карта Старт — детская под контролем родителя; счёт Копилка — накопительный со свободным доступом к деньгам; вклад Горизонт — срочное размещение с фиксированной ставкой; кредит План — кредит наличными с ежемесячными платежами. Чтобы узнать условия и оформление, назовите продукт. Ипотека, инвестиции, бизнес-счета, премиальные и валютные продукты в учебном каталоге не представлены.','какие продукты есть что предлагаете список услуги ассортимент')
add('G02','general','Как сравнить карты и сбережения',f'Каждый день — дебетовая карта: собственные деньги, обслуживание {p["debit"]["service_month"]} ₽ в месяц, кэшбэк {p["debit"]["cashback_pct"]}% до {p["debit"]["cashback_cap_month"]} ₽ в месяц. Запас — кредитная: заёмные средства, обслуживание {p["credit"]["service_month"]} ₽, покупки с льготой до {p["credit"]["grace_days"]} дней при выполнении условий погашения. Старт — детская для {p["junior"]["age"]}–{p["junior"]["age_max"]} лет, под контролем родителя, без кредита. Копилка — свободные пополнение и снятие, {p["savings"]["rate_pct"]}% годовых, переменная ставка. Горизонт — {p["deposit"]["term_months"]} месяцев, {p["deposit"]["rate_pct"]}% годовых фиксированно, от {p["deposit"]["min_amount"]} ₽, без пополнения и частичного снятия. Для повседневных расходов рассмотрите дебетовую карту; для резерва со свободным доступом — Копилку.','чем отличаются сравни выбрать подходит лучше разница вклад накопительный кредитная дебетовая')
t=c['transfers']
add('G03','general','Переводы с дебетового счёта',f'Переводы между своими счетами и другим клиентам Демо-банка с дебетового счёта бесплатные, обычно до {t["internal_minutes"]} минуты. Межбанковский перевод по реквизитам — до {t["external_days"]} рабочих дней; комиссия за него в базе не задана. По СБП другим людям: до {t["sbp_free_month"]} ₽ в месяц без комиссии, сверх лимита {t["sbp_over_pct"]}% с суммы превышения, максимум {t["sbp_over_max"]} ₽ за перевод. Условия переводов себе в другой банк отдельно не описаны. Чат не выполняет переводы и не проверяет конкретную операцию.','перевод деньги сроки сбп комиссия отправить получатель')
add('G04','general','Где найти реквизиты баланс и выписку','В учебном приложении выберите нужный счёт или карту → «Реквизиты», чтобы посмотреть номер счёта и банковские реквизиты. Для истории операций откройте «Выписка», выберите период и скачайте документ. Баланс показывается на экране выбранного счёта. Чат не имеет доступа к реальным счетам, остаткам и операциям и не может назвать ваш баланс. Не присылайте полный номер карты, CVV, ПИН, пароли или коды подтверждения.','номер счета бик баланс остаток справка выписка посмотреть')
add('G05','general','Безопасность и блокировка карты','Общая инструкция: откройте нужную карту в учебном приложении → «Настройки» → «Заблокировать» и подтвердите действие. Чат сам карту не блокирует. При потере карты, неизвестном списании или подозрении на мошенничество незамедлительно используйте официальный канал своего реального банка: приложение или номер с оборота карты. Не сообщайте ПИН, CVV, пароль и СМС-коды. Если код уже передан постороннему, прекратите общение с ним и обратитесь в банк. Для вымышленного Демо-банка нет реального телефона и службы поддержки.','как заблокировать карту мошенник потерял украли неизвестное списание безопасность')
add('G06','general','Связь с поддержкой и ограничения демо','В учебном приложении раздел «Помощь» → «Чат» позволяет описать проблему и попросить сотрудника. В этом прототипе реальной очереди операторов нет: режим помощи сотруднику только готовит краткое описание проблемы и черновик ответа. Чат не открывает счета, не одобряет кредит, не переводит деньги, не блокирует карты и не проверяет личные операции. Сведения о продуктах вымышлены. Для реального инцидента используйте приложение своего банка или номер на обороте карты.','оператор человек сотрудник поддержка жалоба связаться')
